#!/usr/bin/env python3
"""Turn an App Control rules CSV (as generated by AppControlUI / exported from the console) into the
bundled Common-applications seed file `catalog_seed.csv`.

  python3 tools/sanitize_csv.py SentinelOne_202611231035.csv            # writes ./catalog_seed.csv (merges with existing)
  python3 tools/sanitize_csv.py in.csv --replace                         # start the seed from scratch

What it does
  * C:\\Users\\<name>\\...  and  /Users/<name>/...  become  C:\\Users\\*\\...  /Users/*/...  (same rule as the UI's "Any user folder")
  * the version is read from the Description ("Zoom 6.1.5" -> 6.1.5)
  * rows for the same OS + app + publisher + version + (generalised) folder collapse into ONE entry; if they
    differed only by process name the entry becomes a folder-wide rule (process and hash blank)
  * drops rules in temp/build folders (\\Temp\\, bin\\Debug, /tmp ...), rules that are not valid for the console, and rows the built-in list already covers
No network access; nothing is sent anywhere.
"""
import argparse
import csv
import re
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(ROOT))
import catalog          # noqa: E402
import s1client as c    # noqa: E402

COLS = ["name", "publisher", "os", "version", "install_path", "process", "hash", "kind"]
SHARED = re.compile(r"^(public|default|default user|all users|shared)$", re.I)


def generalise(p):
    m = re.match(r"^([A-Za-z]:\\Users\\)([^\\]+)(\\.*)?$", p, re.I)
    if m and not SHARED.match(m[2]):
        return m[1] + "*" + (m[3] or "")
    m = re.match(r"^(/Users/)([^/]+)(/.*)?$", p)
    if m and not SHARED.match(m[2]):
        return m[1] + "*" + (m[3] or "")
    return p


# throw-away locations: allowing these would whitelist temp/build output, so they never enter the seed
NOISE = re.compile(r"\\temp\\|\\tmp\\|\\bin\\(debug|release)\\|\\obj\\|\\\$recycle\.bin\\|\\inetcache\\|^/(private/)?(tmp|var/folders)/|/\.Trash/", re.I)


def version_of(name, desc):
    d = (desc or "").strip()
    d = re.sub(r"\s+-\s+\d+\s+endpoint\(s\)\s*$", "", d)
    if d.lower().startswith(name.lower()):
        d = d[len(name):]
    d = re.sub(r"\(per-user install\)", "", d, flags=re.I).strip()
    return d if re.fullmatch(r"\d[\w.+\-]*(?:,\s*\d[\w.+\-]*)*", d) else ""


def builtin_index():
    seed = catalog.SEED[:catalog.BUILTIN_COUNT]
    full = {(e["os"], e["publisher"].lower(), e["install_path"].lower(), e["process"].lower()) for e in seed}
    vend = {(e["os"], e["publisher"].lower()) for e in seed if e["kind"] == "vendor" and not e["install_path"]}
    return full, vend


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("src"); ap.add_argument("--out", default=str(ROOT / "catalog_seed.csv")); ap.add_argument("--replace", action="store_true")
    a = ap.parse_args()
    rows = list(csv.DictReader(open(a.src, encoding="utf-8-sig")))
    full, vend = builtin_index()
    stats = dict(read=len(rows), invalid=0, builtin=0, generalised=0, noise=0)
    groups = {}
    for r in rows:
        try:
            r = c.clean_rule(r)
        except c.S1Error:
            stats["invalid"] += 1; continue
        os_, pub, path, proc = r["OS Type"], r["Publisher"], r["Path"], r["Process"]
        if not (path or proc or r["Hash SHA-256"]):
            if (os_, pub.lower()) in vend:
                stats["builtin"] += 1; continue
            kind = "vendor"
        else:
            kind = "app"
        if (os_, pub.lower(), path.lower(), proc.lower()) in full:
            stats["builtin"] += 1; continue
        if NOISE.search(path + "\\") or NOISE.search(path + "/"):
            stats["noise"] += 1; continue
        g = generalise(path)
        stats["generalised"] += g != path
        name = r["Rule Name"]
        key = (os_, name.lower(), pub.lower(), version_of(name, r["Description"]), g.lower(), kind)
        grp = groups.setdefault(key, {"name": name, "publisher": pub, "os": os_, "version": key[3], "install_path": g,
                                      "kind": kind, "procs": set(), "hashes": set()})
        grp["procs"].add(proc); grp["hashes"].add(r["Hash SHA-256"])
    out = {}
    if not a.replace and Path(a.out).exists():
        for r in csv.DictReader(open(a.out, encoding="utf-8")):
            out[(r["os"], r["name"].lower(), r["publisher"].lower(), r["version"], r["install_path"].lower(), r["kind"])] = r
    for key, g in groups.items():
        single = len(g["procs"]) == 1
        out[key] = {"name": g["name"], "publisher": g["publisher"], "os": g["os"], "version": g["version"],
                    "install_path": g["install_path"], "kind": g["kind"],
                    "process": next(iter(g["procs"])) if single else "",
                    "hash": next(iter(g["hashes"])) if single and len(g["hashes"]) == 1 else ""}
    final = sorted(out.values(), key=lambda r: (r["os"], r["name"].lower(), r["version"], r["install_path"].lower()))
    with open(a.out, "w", newline="", encoding="utf-8") as f:
        w = csv.DictWriter(f, fieldnames=["name", "publisher", "os", "version", "install_path", "process", "hash", "kind"])
        w.writeheader(); w.writerows(final)
    print(f"read {stats['read']} rules | invalid {stats['invalid']} | already built in {stats['builtin']} | temp/build paths dropped {stats['noise']} | "
          f"user paths generalised {stats['generalised']} | -> {len(final)} entries in {a.out}")


if __name__ == "__main__":
    main()
